cat >> src/orders/domain/order.ts <<'EOF'

/**
 * Domain rule: two distinct pending orders of the same customer can be merged.
 * Returns the updated target (holding both item lists) and the cancelled source.
 */
export function merge(source: Order, target: Order): { source: Order; target: Order } {
  if (source.id === target.id) throw new OrderStateError("cannot merge order " + source.id + " into itself");
  if (source.customerId !== target.customerId) throw new OrderStateError("orders belong to different customers");
  if (target.status !== "pending") throw new OrderStateError("order " + target.id + " is " + target.status);
  const cancelledSource = cancel(source);
  return { source: cancelledSource, target: { ...target, items: [...target.items, ...source.items] } };
}
EOF
python3 - <<'EOF'
p='src/orders/routes/order-routes.ts'
s=open(p).read()
s=s.replace('import type { InMemoryOrderStore }','import { merge, OrderStateError } from "../domain/order.ts";\nimport type { InMemoryOrderStore }')
s=s.replace('''  return router;''','''  router.add("POST", "/orders/merge", withCustomer(deps.sessions, (req, _params, customer) => {
    const { sourceId, targetId } = (req.body ?? {}) as { sourceId?: unknown; targetId?: unknown };
    if (typeof sourceId !== "string" || typeof targetId !== "string")
      return { status: 400, body: { error: "sourceId and targetId required" } };
    const source = deps.orders.get(sourceId), target = deps.orders.get(targetId);
    if (!source || source.customerId !== customer.id || !target || target.customerId !== customer.id)
      return { status: 404, body: { error: "order not found" } };
    try {
      const merged = merge(source, target);
      deps.orders.save(merged.target);
      deps.orders.save(merged.source);
      return { status: 200, body: merged.target };
    } catch (e) {
      if (e instanceof OrderStateError) return { status: 409, body: { error: e.message } };
      throw e;
    }
  }));

  return router;''')
open(p,'w').write(s)
EOF
