import { readFileSync } from 'node:fs';
const order=(id,customerId='c',status='pending',items=[id])=>({id,customerId,status,items});
function setup(seed=[order('s','c','pending',['x','x']),order('t','c','pending',['z']),order('u')]) {
 const orders=new InMemoryOrderStore(seed); let saves=0;
 const save=orders.save.bind(orders); orders.save=o=>{saves++;save(o)};
 const router=orderRoutes(new Router(),{orders,sessions:{lookup:t=>t==='good'?{id:'c'}:undefined}});
 return {orders,get saves(){return saves},send:(body:any={sourceId:'s',targetId:'t'},authorization:any='Bearer good')=>router.handle({method:'POST',path:'/orders/merge',headers:{authorization},body})};
}
function rejection(f,body:any={sourceId:'s',targetId:'t'},auth:any='Bearer good') {const before=structuredClone(f.orders.all());const r=f.send(body,auth);assert.ok(r.status>=400&&r.status<500,`expected 4xx, got ${r.status}`);assert.deepEqual(f.orders.all(),before);assert.equal(f.saves,0)}
