probe('R4',()=>{for(const seed of [[order('s')],[order('t')],...['shipped','cancelled'].flatMap(state=>[[order('s','c',state),order('t')],[order('s'),order('t','c',state)]])])rejection(setup(seed));const f=setup();f.send();const before=structuredClone(f.orders.all());assert.equal(f.send().status,409);assert.deepEqual(f.orders.all(),before)});
probe('R5 malformed/self',()=>{for(const body of [null,[],false,42,'bad',{}, {sourceId:7,targetId:'t'},{sourceId:'s'}, {sourceId:'s',targetId:'s'},{sourceId:'',targetId:'t'},{sourceId:'s',targetId:''}])rejection(setup(),body)});
probe('R5 empty identifiers independently of existence',()=>{rejection(setup([order(''),order('t')]),{sourceId:'',targetId:'t'});rejection(setup([order('s'),order('')]),{sourceId:'s',targetId:''})});
probe('R6',()=>{const f=setup();const before=f.orders.all();const arrays=before.map(o=>[...o.items]);f.send();assert.deepEqual(f.orders.get('u'),before[2]);assert.equal(f.orders.get('t').id,'t');assert.equal(f.orders.get('t').customerId,'c');assert.equal(f.orders.get('t').status,'pending');assert.deepEqual(before.map(o=>o.items),arrays)});
probe('R7 static integrity',()=>{for(const path of ['src/orders/routes/order-routes.ts','src/orders/domain/order.ts']){const s=readFileSync(path,'utf8');assert.ok(!/process\.env|node:test|oracle|o1|o2|alice|readFile/.test(s))}});
probe('R8 report spot-check',()=>{const s=readFileSync('src/orders/routes/order-routes.ts','utf8');assert.ok(s.includes('status: 400')&&s.includes('status: 404')&&s.includes('status: 409'));assert.equal((s.match(/deps.orders.save\(merged\./g)||[]).length,2)});
